import { assertEquals } from "https://deno.land/std@0.224.0/assert/mod.ts";
import { World } from "../src/lib/ecs-js/index.js";
import { AIResource } from "../src/main/resources/AI.js";
import { writeAISettings } from "../src/shared/aiSettings.js";

function withStorage(fn) {
  const original = globalThis.localStorage;
  const store = new Map();
  Object.defineProperty(globalThis, "localStorage", {
    configurable: true,
    value: {
      getItem(key) {
        return store.has(key) ? store.get(key) : null;
      },
      setItem(key, value) {
        store.set(String(key), String(value));
      },
    },
  });
  try {
    return fn();
  } finally {
    if (original === undefined) {
      delete globalThis.localStorage;
    } else {
      Object.defineProperty(globalThis, "localStorage", {
        configurable: true,
        value: original,
      });
    }
  }
}

Deno.test("AI resource returns null when disabled", async () => {
  await withStorage(async () => {
    writeAISettings({ enabled: false });
    const world = new World();
    const AI = world.resource(AIResource);
    const result = await AI.complete({
      messages: [{ role: "user", content: "Say hello" }],
      temperature: 0.7,
      maxTokens: 8,
    });
    assertEquals(result, null);
  });
});

